import type { Unit, Lesson } from "@/types";

/**
 * CURRICULUM — Finance Duolingo
 * Cấu trúc: Units → Lessons → Questions
 * Mỗi Unit có 4-5 lessons. Mỗi lesson có 5-7 questions đa dạng.
 *
 * Quy ước:
 *  - 4 choices cho multiple-choice, 1 đáp án đúng
 *  - true-false: đáp án là boolean
 *  - fill-blank: đáp án là string, so sánh case-insensitive
 *  - match-pairs: cặp left-right, kéo thả hoặc chọn
 *
 * LOCALIZATION (Việt Nam):
 *  - Tiền tệ: VNĐ (đồng). Quy ước: 1 triệu = 1.000.000đ
 *  - Ngân hàng: Vietcombank, Techcombank, MB Bank, ACB, TPBank...
 *  - Thị trường: HOSE, HNX, UPCOM
 *  - Sản phẩm: Tiết kiệm có kỳ hạn, chứng chỉ tiền gửi, quỹ mở VCBF/VinaCapital,
 *    chứng chỉ quỹ ETF FUEVFVN, trái phiếu chính phủ, BHXH/BHYT/BHTN
 *  - Thuế: Thuế TNCN, MST, quyết toán thuế
 *  - Ví dụ đời thường: Grab, Shopee, cafe 30k, cơm 30-40k, thuê phòng trọ HN/SG
 */

